import React from 'react'
import Box from '@mui/material/Box';
import TextField from '@mui/material/TextField';

function TeknikSozluk() {
  return (
    <section className='teknikSozlukContainer'>
      <img src="../images/teknik-sozluk.png" alt="Teknik Sözlük"  />
      <h1 style={styles.title}>Teknik Sözlük</h1>
      <p style={styles.text}>A’dan Z’ye tüm teknoloji terimlerinin tanımlarını senin için hazırladığımız teknoloji sözlüğünde bulabilirsin!</p>

      <Box
        component="form"
        sx={{ '& .MuiTextField-root': { m: 1, width: '25ch' } }}
        noValidate
        autoComplete="off"
      >
        <div>
          <TextField id="outlined-search" label="Search field" type="search" />
        </div>
      </Box>
    </section>
  )
}

const styles = {
  teknikSozlukContainer: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
  }
}

export default TeknikSozluk
